INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('ФКЗ о Правительстве','Кто входит в состав Правительства РФ согласно ФКЗ № 4-ФКЗ?','["Председатель, заместители Председателя и федеральные министры","Президент, Председатель и губернаторы","Председатель, сенаторы и федеральные министры","Президент и все руководители федеральных служб"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ','статья 4','https://www.garant.ru/products/ipo/prime/doc/74765733/','Состав Правительства включает Председателя, его заместителей и федеральных министров.',true),
('ФКЗ о Правительстве','Входит ли Президент РФ в состав Правительства РФ в качестве его члена?','["Да","Нет"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ','статья 4','https://www.garant.ru/products/ipo/prime/doc/74765733/','Президент осуществляет общее руководство Правительством, но не перечислен среди его членов.',true),
('ФКЗ о Правительстве','Кто руководит деятельностью федеральных министерств по обороне, безопасности, внутренним и иностранным делам согласно установленной структуре?','["Государственная Дума","Президент Российской Федерации","Счётная палата","Совет Федерации"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_366950/a1bca0dec80440197ca29ebcf0a1344c6d61c906/','Президент руководит органами, ведающими перечисленными направлениями, в соответствии со структурой федеральных органов исполнительной власти.',true),
('ФКЗ о Правительстве','Могут ли Президент и Правительство осуществлять руководство деятельностью федеральных органов исполнительной власти в соответствии с установленной структурой?','["Да","Нет"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_366950/a1bca0dec80440197ca29ebcf0a1344c6d61c906/','Руководство ими осуществляется Президентом и Правительством по распределению в структуре федеральной исполнительной власти.',true),
('ФКЗ о Правительстве','Кто организует реализацию внутренней и внешней политики РФ?','["Правительство Российской Федерации","Только органы местного самоуправления","Центральная избирательная комиссия","Конституционный Суд"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ','статья 13','https://www.consultant.ru/document/cons_doc_LAW_366950/6e0710d16ad0b6822dffa58aefee38d5fb93fe18/','Статья 13 относит организацию реализации внутренней и внешней политики к общим полномочиям Правительства.',true),
('ФКЗ о Правительстве','Обеспечивает ли Правительство единство системы исполнительной власти РФ?','["Верно","Неверно"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ','статья 13','https://www.consultant.ru/document/cons_doc_LAW_366950/6e0710d16ad0b6822dffa58aefee38d5fb93fe18/','Правительство обеспечивает единство системы исполнительной власти, координирует и контролирует деятельность органов исполнительной власти.',true),
('ФКЗ о Правительстве','Вправе ли Правительство координировать деятельность органов публичной власти в рамках единой системы исполнительной власти?','["Да","Нет"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ','статья 13','https://www.consultant.ru/document/cons_doc_LAW_366950/6e0710d16ad0b6822dffa58aefee38d5fb93fe18/','Правительство обеспечивает взаимодействие органов публичной власти и координацию их деятельности в предусмотренных законом пределах.',true),
('ФКЗ о Правительстве','Какой орган осуществляет регулирование экономических процессов в соответствии с Конституцией и законодательством?','["Центральная избирательная комиссия","Правительство РФ","Генеральная прокуратура","Конституционный Суд"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ','статья 18','https://www.garant.ru/products/ipo/prime/doc/74765733/','Статья 18 относит регулирование экономических процессов к полномочиям Правительства.',true),
('ФКЗ о Правительстве','Обеспечение свободы экономической деятельности относится к полномочиям Правительства РФ.','["Верно","Неверно"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ','статья 18','https://www.garant.ru/products/ipo/prime/doc/74765733/','Правительство обеспечивает единство экономического пространства и свободу экономической деятельности.',true),
('ФКЗ о Правительстве','Кто прогнозирует социально-экономическое развитие РФ и разрабатывает программы развития отраслей экономики?','["Государственная Дума","Правительство РФ","Счётная палата","Генеральная прокуратура"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ','статья 18','https://www.garant.ru/products/ipo/prime/doc/74765733/','В сфере экономики Правительство прогнозирует развитие страны, разрабатывает и реализует отраслевые программы.',true),
('ФКЗ о Правительстве','Осуществляет ли Правительство меры по защите суверенитета и обеспечению обороны страны?','["Верно","Неверно"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ','статья 24','https://www.consultant.ru/document/cons_doc_LAW_366950/ac08bf2201b09f39f39301debc5a3a2ad2c64e96/','Статья 24 включает защиту суверенитета, территориальной целостности и меры по обороне и безопасности в полномочия Правительства.',true),
('ФКЗ о Правительстве','Кто возглавляет Правительство Российской Федерации и организует его работу?','["Председатель Государственной Думы","Председатель Правительства РФ","Председатель Совета Федерации","Генеральный прокурор"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ','статья 27','https://constitution.garant.ru/law_evolution/74865733/chapter/3e01a7fa47957b2f627d012fe630f5c6/','Председатель Правительства возглавляет Правительство и организует его работу.',true),
('Публичная власть субъектов','Каким федеральным законом установлены общие принципы организации публичной власти в субъектах РФ?','["№ 414-ФЗ от 21.12.2021","№ 210-ФЗ от 27.07.2010","№ 172-ФЗ от 28.06.2014","№ 59-ФЗ от 02.05.2006"]'::jsonb,0,'ФЗ от 21.12.2021 № 414-ФЗ','статья 1','https://www.consultant.ru/document/cons_doc_LAW_404070/','Закон № 414-ФЗ регулирует общие принципы организации публичной власти в субъектах РФ.',true),
('Публичная власть субъектов','Какой принцип прямо закреплён для органов единой системы публичной власти в субъекте РФ?','["Приоритет местных ведомственных инструкций над Конституцией","Обеспечение соблюдения и защиты прав и свобод человека","Отказ от судебного контроля","Обязательное единоначалие всех муниципальных органов"]'::jsonb,1,'ФЗ от 21.12.2021 № 414-ФЗ','статья 2','https://www.consultant.ru/document/cons_doc_LAW_404070/b1cb0c1385c89e2396c3f614f4158981032a000e/','Соблюдение и защита прав и свобод человека — один из основных принципов деятельности органов публичной власти в субъекте.',true),
('Публичная власть субъектов','Должны ли органы государственной власти субъекта РФ обеспечивать соответствие принимаемых актов Конституции РФ и федеральным законам?','["Да","Нет"]'::jsonb,0,'ФЗ от 21.12.2021 № 414-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_404070/dd1341b06a7d5aff370204a361fa7a537de31f00/','Органы субъекта обеспечивают соответствие своих конституций, уставов, законов и иных НПА федеральному праву.',true),
('Публичная власть субъектов','Входят ли органы государственной власти субъекта РФ в единую систему публичной власти Российской Федерации?','["Да","Нет"]'::jsonb,0,'ФЗ от 21.12.2021 № 414-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_404070/dd1341b06a7d5aff370204a361fa7a537de31f00/','Статья 4 рассматривает органы государственной власти субъекта в единой системе публичной власти РФ.',true),
('Стратегическое планирование','Какие виды деятельности образуют стратегическое планирование по закону № 172-ФЗ?','["Целеполагание, прогнозирование, планирование и программирование","Только бюджетирование и контроль","Только выборы и назначение должностных лиц","Лишь подготовка государственных программ"]'::jsonb,0,'ФЗ от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Статья 3 включает все четыре перечисленные взаимосвязанные деятельности.',true),
('Стратегическое планирование','Что в законе о стратегическом планировании означает целеполагание?','["Определение направлений, целей и приоритетов развития и безопасности","Финансовый аудит проведённых закупок","Выдачу разрешений и лицензий","Подсчёт итогов голосования"]'::jsonb,0,'ФЗ от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Целеполагание предполагает определение направлений, целей и приоритетов социально-экономического развития и безопасности.',true),
('Стратегическое планирование','Как определяется прогнозирование в системе стратегического планирования?','["Разработка научно обоснованных представлений о рисках, направлениях и показателях развития","Принятие федеральных законов в трёх чтениях","Оформление протоколов заседаний","Надзор за хозяйственными обществами"]'::jsonb,0,'ФЗ от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Прогнозирование касается научно обоснованных представлений о рисках, угрозах и результатах развития.',true),
('Стратегическое планирование','С чем связано программирование в стратегическом планировании?','["Разработка и реализация государственных и муниципальных программ","Создание электронных систем органов власти","Лишь контроль дисциплины служащих","Ведение персонального учёта избирателей"]'::jsonb,0,'ФЗ от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Программирование — это разработка и реализация государственных и муниципальных программ, направленных на достижение установленных целей.',true),
('Стратегическое планирование','Относится ли комплексная оценка хода и итогов реализации стратегических документов к мониторингу и контролю?','["Верно","Неверно"]'::jsonb,0,'ФЗ от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','В определение мониторинга и контроля входит комплексная оценка хода и итогов реализации документов.',true),
('Стратегическое планирование','Изменяется ли период действия документа стратегического планирования при его «корректировке» в смысле закона № 172-ФЗ?','["Да, обязательно","Нет"]'::jsonb,1,'ФЗ от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Корректировка означает изменение документа без изменения периода, на который он разработан.',true),
('Стратегическое планирование','На каких уровнях разрабатываются документы стратегического планирования?','["Только федеральном","Федеральном, региональном и муниципальном","Только региональном и муниципальном","Только федеральном и региональном"]'::jsonb,1,'ФЗ от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','Статья 11 предусматривает разработку документов на федеральном, региональном и муниципальном уровнях.',true),
('Стратегическое планирование','Кто координирует разработку и реализацию документов стратегического планирования по вопросам своего ведения?','["Президент РФ и Правительство РФ","Только Счётная палата","Только Центральная избирательная комиссия","Только Верховный Суд"]'::jsonb,0,'ФЗ от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','Координация осуществляется Президентом и Правительством по вопросам, находящимся в их ведении.',true),
('Государственные услуги','Обязаны ли органы предоставлять государственные и муниципальные услуги в соответствии с административными регламентами?','["Да","Нет"]'::jsonb,0,'ФЗ от 27.07.2010 № 210-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_103023/1ad52ab9177bbc53835519b62dbd061ddcc96223/','Предоставление услуг в соответствии с административными регламентами — установленная законом обязанность органов.',true),
('Государственные услуги','Должен ли орган обеспечить возможность получения услуги в электронной форме, если это не запрещено законом?','["Да","Нет"]'::jsonb,0,'ФЗ от 27.07.2010 № 210-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_103023/1ad52ab9177bbc53835519b62dbd061ddcc96223/','Закон предусматривает электронную форму предоставления услуги, если это не запрещено законом, с оговорками о возможной исключительно электронной форме.',true),
('Государственные услуги','Могут ли органы обмениваться необходимыми документами по межведомственному запросу без взимания платы, если закон это предусматривает?','["Да","Нет"]'::jsonb,0,'ФЗ от 27.07.2010 № 210-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_103023/1ad52ab9177bbc53835519b62dbd061ddcc96223/','Статья 6 предусматривает безвозмездное предоставление необходимой информации по межведомственным запросам с установленными исключениями.',true),
('Государственные услуги','Может ли МФЦ выдавать заявителям документы по результатам предоставления государственной услуги?','["Да","Нет"]'::jsonb,0,'ФЗ от 27.07.2010 № 210-ФЗ','статья 16','https://www.consultant.ru/document/cons_doc_LAW_103023/a2588b2a1374c05e0939bb4df8e54fc0dfd6e000/','Статья 16 прямо относит выдачу результатов предоставления услуг к функциям МФЦ, если иное не установлено законом.',true),
('Государственные услуги','Может ли МФЦ оформлять бумажное подтверждение содержания электронного документа по результатам услуги?','["Да, в установленном порядке","Нет, ни при каких условиях","Только по решению суда","Только по распоряжению налогового органа"]'::jsonb,0,'ФЗ от 27.07.2010 № 210-ФЗ','статья 16','https://www.consultant.ru/document/cons_doc_LAW_103023/a2588b2a1374c05e0939bb4df8e54fc0dfd6e000/','МФЦ вправе оформлять бумажные документы, подтверждающие содержание электронных результатов услуг, по требованиям Правительства РФ.',true),
('Обращения граждан','Каков общий срок рассмотрения письменного обращения гражданина компетентным органом?','["10 дней","15 дней","30 дней","60 дней"]'::jsonb,2,'ФЗ от 02.05.2006 № 59-ФЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_59999/23fb391f3632e3f68a11e40c5a7711f3513cc674/','Общее правило — 30 дней со дня регистрации обращения; закон содержит специальное исключение.',true),
('Обращения граждан','На какой максимальный дополнительный срок допускается продление рассмотрения обращения в предусмотренных законом исключительных случаях?','["10 дней","15 дней","30 дней","60 дней"]'::jsonb,2,'ФЗ от 02.05.2006 № 59-ФЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_59999/23fb391f3632e3f68a11e40c5a7711f3513cc674/','В исключительных случаях срок может быть продлён не более чем на 30 дней с уведомлением гражданина.',true),
('Обращения граждан','Нужно ли уведомлять гражданина о продлении срока рассмотрения его обращения?','["Да","Нет"]'::jsonb,0,'ФЗ от 02.05.2006 № 59-ФЗ','статья 12','https://www.consultant.ru/document/cons_doc_LAW_59999/23fb391f3632e3f68a11e40c5a7711f3513cc674/','Статья 12 требует уведомлять гражданина о продлении срока рассмотрения обращения.',true),
('Обращения граждан','Кто проводит личный приём граждан в государственных органах и органах местного самоуправления?','["Только глава государства","Руководители и уполномоченные ими лица","Только сотрудники полиции","Только депутаты Государственной Думы"]'::jsonb,1,'ФЗ от 02.05.2006 № 59-ФЗ','статья 13','https://www.nalog.gov.ru/files/docs/fz/59_fz.htm','Личный приём проводится руководителями органов и уполномоченными на то лицами.',true)
